-- Modify "auth_sessions" table
ALTER TABLE "auth_sessions" ADD CONSTRAINT "auth_session_user_hash_unique" UNIQUE ("user_id", "token_hash");
-- Create "passkey_management_intents" table
CREATE TABLE "passkey_management_intents" ("id" uuid NOT NULL, "user_id" uuid NOT NULL, "session_hash" bytea NOT NULL, "rp_id" text NOT NULL, "origin" text NOT NULL, "action" text NOT NULL, "target_credential_id" bytea NULL, "challenge" bytea NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz NULL, "authorization_credential_id" bytea NULL, "authorized_at" timestamptz NULL, "registration_challenge" bytea NULL, "registration_consumed_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "passkey_management_authorizer_owner_fk" FOREIGN KEY ("user_id", "authorization_credential_id") REFERENCES "passkey_credentials" ("user_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "passkey_management_intents_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "passkey_accounts" ("user_id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "passkey_management_session_owner_fk" FOREIGN KEY ("user_id", "session_hash") REFERENCES "auth_sessions" ("user_id", "token_hash") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "passkey_management_target_owner_fk" FOREIGN KEY ("user_id", "target_credential_id") REFERENCES "passkey_credentials" ("user_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "passkey_management_action" CHECK (action = ANY (ARRAY['add'::text, 'revoke'::text])), CONSTRAINT "passkey_management_authorization" CHECK (((authorized_at IS NULL) AND (authorization_credential_id IS NULL) AND (registration_challenge IS NULL)) OR ((authorized_at IS NOT NULL) AND isfinite(authorized_at) AND (authorization_credential_id IS NOT NULL) AND (consumed_at IS NOT NULL) AND (authorized_at >= consumed_at) AND (authorized_at < expires_at) AND (((action = 'add'::text) AND (registration_challenge IS NOT NULL)) OR ((action = 'revoke'::text) AND (registration_challenge IS NULL) AND (authorization_credential_id <> target_credential_id))))), CONSTRAINT "passkey_management_consumed" CHECK ((consumed_at IS NULL) OR (isfinite(consumed_at) AND (consumed_at >= created_at) AND (consumed_at < expires_at))), CONSTRAINT "passkey_management_expiry" CHECK (isfinite(created_at) AND isfinite(expires_at) AND (expires_at > created_at) AND (expires_at <= (created_at + '00:05:00'::interval))), CONSTRAINT "passkey_management_hash" CHECK (octet_length(session_hash) = 32), CONSTRAINT "passkey_management_nonce" CHECK ((octet_length(challenge) = 32) AND ((registration_challenge IS NULL) OR (octet_length(registration_challenge) = 32))), CONSTRAINT "passkey_management_registration_consumed" CHECK ((registration_consumed_at IS NULL) OR ((action = 'add'::text) AND (authorized_at IS NOT NULL) AND isfinite(registration_consumed_at) AND (registration_consumed_at >= authorized_at) AND (registration_consumed_at < expires_at))), CONSTRAINT "passkey_management_rp" CHECK ((rp_id = 'localhost'::text) AND (origin = ANY (ARRAY['http://localhost:5173'::text, 'http://localhost:5174'::text]))), CONSTRAINT "passkey_management_target" CHECK (((action = 'add'::text) AND (target_credential_id IS NULL)) OR ((action = 'revoke'::text) AND (target_credential_id IS NOT NULL))));
-- Create index "passkey_management_expiry_idx" to table: "passkey_management_intents"
CREATE INDEX "passkey_management_expiry_idx" ON "passkey_management_intents" ("expires_at");
